import sympy
import logging
from enum import Enum
from dataclasses import dataclass
from typing import List, Any, Optional, Union

from .strategies import SymbolicStrategy, NumericalStrategy
from .exceptions import ParsingError, VerificationError, MathSolverError

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("MathSolver")

class SolveMode(Enum):
    EXACT = "exact"
    NUMERICAL = "numerical"
    AUTO = "auto"

@dataclass
class SolverResult:
    value: Any
    strategy: str
    verified: bool
    residual: float

class MathSolver:
    """
    The core engine for mathematical resolution.
    Implements the Strategy pattern to switch between symbolic and numerical solvers.
    """
    def __init__(self, default_precision: int = 50):
        self._strategies = {
            SolveMode.EXACT: SymbolicStrategy(),
            SolveMode.NUMERICAL: NumericalStrategy(precision=default_precision)
        }

    def _parse_expression(self, expr_str: str) -> sympy.Expr:
        try:
            return sympy.sympify(expr_str)
        except Exception as e:
            logger.error(f"Parsing failed for expression: {expr_str}")
            raise ParsingError(f"Invalid mathematical expression: {e}")

    def _verify_solution(self, expression: sympy.Expr, var: sympy.Symbol, solution: Any) -> float:
        """
        Plugs the solution back into the expression to calculate the residual.
        Residual should be close to 0.
        """
        try:
            # Substitute solution into expression
            result = expression.subs(var, solution)
            # Evaluate numerically
            residual = float(result.evalf())
            return abs(residual)
        except Exception:
            return float('inf')

    def solve(self, expression_str: str, variables_str: List[str], mode: SolveMode = SolveMode.AUTO) -> SolverResult:
        """
        Main entry point for solving equations.
        """
        expr = self._parse_expression(expression_str)
        vars_sym = [sympy.symbols(v) for v in variables_str]
        
        # Auto-mode logic: Try symbolic first, fallback to numerical
        if mode == SolveMode.AUTO:
            try:
                return self.solve(expression_str, variables_str, mode=SolveMode.EXACT)
            except (NotImplementedError, MathSolverError):
                logger.info("Symbolic solver failed, falling back to numerical.")
                mode = SolveMode.NUMERICAL

        strategy = self._strategies[mode]
        strategy_name = strategy.__class__.__name__
        
        logger.info(f"Executing {strategy_name} for expression: {expression_str}")
        solutions = strategy.solve(expr, vars_sym)
        
        if not solutions:
            raise MathSolverError("No solutions found.")

        # Verification of the first solution found
        primary_sol = solutions[0]
        residual = self._verify_solution(expr, vars_sym[0], primary_sol)
        is_verified = residual < 1e-10

        if not is_verified:
            logger.warning(f"Solution {primary_sol} failed verification. Residual: {residual}")

        return SolverResult(
            value=solutions,
            strategy=strategy_name,
            verified=is_verified,
            residual=residual
        )

# Example Usage
if __name__ == "__main__":
    solver = MathSolver()
    
    # Test 1: Symbolic Linear
    res1 = solver.solve("x**2 - 4", ["x"], SolveMode.EXACT)
    print(f"Linear Result: {res1}")

    # Test 2: Numerical Transcendental
    res2 = solver.solve("sympy.sin(x) - 0.5", ["x"], SolveMode.NUMERICAL)
    print(f"Transcendental Result: {res2}")